"""The EPT Hankel-block tables generated by ``tools/ptgen`` (``tables/ept_hankel_<22|13>.npz``)."""
import os

import numpy as np

TABLE_DIR = os.path.join(os.path.dirname(__file__), 'tables')


def read_tables(prefix):
    """``(names, lnm, table)`` of the blocks ``<prefix>_l_n_m`` (``prefix`` '22' or '13').

    ``names`` are sorted as strings, ``lnm`` ``(nblocks, 3)`` int64, ``table``
    ``(nblocks, nterms, 7)``: per row the powers of (mu, f, b1, b2, bG2, bGamma3) and the
    coefficient, zero-padded rows at the end.
    """
    with np.load(os.path.join(TABLE_DIR, f'ept_hankel_{prefix}.npz'), allow_pickle=False) as data:
        return [str(name) for name in data['names']], data['lnm'], data['table']
